        // The oracle expects totalSupply > 5,000,000,000e9
        assertGt(totalSupply, 5000000000e9, "totalSupply should be > 5B tokens");

        // Additionally, we can show the inconsistency
        // In a correct implementation, sumBalances should equal totalSupply
        // But due to the bug, totalSupply will be greater than sumBalances
        assertGt(totalSupply, sumBalances, "totalSupply should be greater than sum of balances due to double deduction bug");

