        uint256 expectedTotalSupplyReduction = expectedBurnFee;
        console.log("Expected burn fee:", expectedBurnFee);
        console.log("Expected total supply reduction:", expectedTotalSupplyReduction);
        console.log("Actual total supply reduction:", initialTotalSupply - totalSupply);
    }




